// ============================================================
//  ИМЯ КЛИЕНТА — И БОЛЬШЕ НИЧЕГО
// ============================================================
//
// Настройки клиента лежат ФАЙЛОМ на сервере: /data/clients/<имя>.json.
// Приложение читает его при каждом запросе, перезапуск не нужен.
//
// ПОЧЕМУ ЗДЕСЬ ТОЛЬКО ИМЯ. До 07.10.2026 эта нода содержала копию всех
// настроек и отправляла их приложению, а приложение ставит присланное ВЫШЕ
// файла. То есть владелец правил бы файл и не видел результата, а причину
// нечем было бы заметить: обе копии по отдельности выглядят правильными.
// Теперь источник настроек один — файл.
//
// Состав файла и пояснение к каждому полю — deploy/clients/client-example.json
// Поменять клиента: заменить строку ниже на имя его файла без .json

return [{ json: { клиент: 'kargin' } }];

// Раскладываем ответ приложения в отдельные сообщения.
//
// Сообщения клиенту и алерт владельцу идут РАЗНЫМ адресатам: клиент не должен
// узнавать о поломке парсера — он должен получать тендеры.
//
// АДРЕСА ЧАТОВ БЕРУТСЯ ИЗ ОТВЕТА ПРИЛОЖЕНИЯ, а не из ноды настроек: источник
// настроек один — файл клиента на сервере. Приложение кладёт адреса в ответ
// ВСЕГДА, в том числе при сбое, — именно при сбое они и нужны больше всего.

const r = $json;
const out = [];

const владельцу = (r && r.ownerChatId) || '';
const клиенту = (r && r.clientChatId) || '';

// Адреса нет — отправлять некуда. Молчать об этом нельзя, пишем в журнал
// выполнения: он виден в n8n и объясняет, почему сообщений не было.
if (!владельцу) {
  console.log('НЕТ АДРЕСА ЧАТА ВЛАДЕЛЬЦА: проверьте ownerChatId в файле клиента '
    + 'на сервере либо переменную OWNER_CHAT_ID');
}

if (!r || r.ok !== true) {
  out.push({
    json: {
      chatId: владельцу,
      text: '🚨 <b>СБОЙ СЕРВИСА</b>\n<b>' + ((r && r.сбой) || 'приложение не ответило') + '</b>'
        + (r && r.подробно ? '\n\n' + r.подробно : '')
        + '\n\n<i>' + new Date().toISOString() + '</i>'
    }
  });
  return out;
}

// Сначала алерт владельцу, если часть запросов не прошла.
if (r.алертВладельцу) {
  out.push({ json: { chatId: владельцу, text: r.алертВладельцу } });
}

// Потом сводка и подробности клиенту. К подробным приложена кнопка расчёта:
// клиент сам выбирает, какой тендер считать подробно.
for (const m of (r.сообщения || [])) {
  out.push({
    json: {
      chatId: клиенту,
      text: m.текст,
      вид: m.вид,
      номер: m.номер,
      клавиатура: m.клавиатура || null
    }
  });
}

// Журнал прогона печатается в выполнение n8n — по нему видно,
// почему клиент не увидел тот или иной тендер.
console.log(JSON.stringify(r.сводка));

// Пустой список — штатный результат: новых тендеров нет, молчим.
return out;

nodes.notes:
Разметка HTML — её задаёт src/notify.js, здесь она должна совпадать. При другом режиме сообщение придёт с видимыми тегами.

Callback Data = «смета:<номер закупки>». Эту же строку разбирает воркфлоу-3: если поменять здесь, он перестанет понимать нажатие. Ограничение Telegram — 64 байта, реестровый номер 44-ФЗ (19 цифр) с префиксом помещается.

ЕСЛИ ПОЛЕ КЛАВИАТУРЫ ПРИ ИМПОРТЕ ОКАЗАЛОСЬ ПУСТЫМ: Reply Markup = Inline Keyboard, Add Keyboard Row, Add Button, Text = 📊 Посчитать смету, Additional Fields → Callback Data = смета:{{ $json.номер }}
